/**
 * TITLE: Generative Bauhaus Kinetic Poster
 * 
 * DESCRIPTION:
 * 1. This piece explores the geometric language of the Bauhaus movement through procedural animation.
 * 2. Each cell in the grid dynamically shifts its form and rotation to create an evolving visual rhythm.
 * 3. The layout is fully responsive, recalculating density and typography to fit any screen dimension.
 */

const COLORS = ['#222222', '#6692B2', '#E36A44', '#EAB043']; // Define the Bauhaus color palette
const BG_COLOR = '#E9E2D0'; // Define the vintage cream background color

let grid = []; // Array to store properties of each grid cell
let cellSize; // Variable for the size of a single cell
let cols, rows; // Variables for number of columns and rows
let marginX, marginY; // Variables for centering the grid
let uiHeight; // Space reserved for the typography at the bottom

function setup() {
  createCanvas(windowWidth, windowHeight); // Create a canvas that fills the window
  initLayout(); // Initialize the grid layout and cell properties
}

function draw() {
  background(BG_COLOR); // Clear the background with the cream color

  noStroke(); // Disable outlines for all shapes
  rectMode(CENTER); // Draw rectangles from the center point

  grid.forEach(cell => { // Iterate through each cell in the grid
    push(); // Save the current transformation state
    translate(cell.x, cell.y); // Move the origin to the cell's position

    cell.currentAngle = lerp(cell.currentAngle, cell.targetAngle, 0.1); // Smoothly interpolate the rotation angle
    rotate(cell.currentAngle); // Apply the rotation to the cell

    cell.timer--; // Decrease the animation timer
    if (cell.timer < 0) { // Check if the timer has expired
      cell.targetAngle += HALF_PI; // Set a new target angle (90 degrees rotation)
      cell.timer = random(120, 300); // Reset the timer with a random duration
      if (random() > 0.8) cell.color = random(COLORS); // Occasionally change the cell color
    }

    fill(cell.color); // Set the fill color for the shape
    let s = cellSize * 0.88; // Set the shape size slightly smaller than the cell
    let r = s; // Set the radius for the rounded corners

    drawShape(0, 0, s, r, cell.shapeType); // Call the function to draw the specific shape
    pop(); // Restore the previous transformation state
  });

  drawTypography(); // Draw the text and lines at the bottom
}

function drawShape(x, y, s, r, type) {
  if (type === 0) { // Shape type 0: Perfect square
    rect(x, y, s, s); // Draw a rectangle
  } else if (type === 1) { // Shape type 1: One corner rounded
    rect(x, y, s, s, r, 0, 0, 0); // Draw a rectangle with one rounded corner
  } else if (type === 2) { // Shape type 2: Two diagonal corners rounded
    rect(x, y, s, s, r, 0, r, 0); // Draw a rectangle with diagonal rounded corners
  } else if (type === 3) { // Shape type 3: Three corners rounded
    rect(x, y, s, s, r, r, r, 0); // Draw a rectangle with three rounded corners
  } else if (type === 4) { // Shape type 4: Perfect circle
    ellipse(x, y, s, s); // Draw an ellipse
  }
}

function drawTypography() {
  push(); // Save the drawing state
  fill(0); // Set text color to black

  let baseUnit = max(width, height); // Get the smallest dimension for scaling
  let titleSize = baseUnit * 0.1; // Scale the title size
  let yearSize = baseUnit * 0.05; // Scale the year text size

  let rightEdge = marginX + (cols - 1) * cellSize + (cellSize * 0.88) / 2; // Calculate the right edge of the grid
  let leftEdge = marginX - (cellSize * 0.88) / 2; // Calculate the left edge of the grid

  let textY = height - marginY * 1.5; // Determine the vertical position for the title
  let lineY = textY + titleSize * 0.6; // Determine the vertical position for the line

  textAlign(RIGHT, BASELINE); // Align text to the right
  textFont('Helvetica'); // Set the font family
  textStyle(BOLD); // Set the font weight to bold
  textSize(titleSize); // Apply the calculated title size
  text("bowwow", rightEdge, textY); // Draw the "bauhaus" text

  stroke(0); // Set line color to black
  strokeWeight(max(2, baseUnit * 0.005)); // Set a responsive line thickness
  line(leftEdge, lineY, rightEdge, lineY); // Draw the horizontal divider line

  noStroke(); // Disable stroke for the following text
  textAlign(RIGHT, TOP); // Align the year text to the right and top
  textSize(yearSize); // Apply the calculated year size
  text("2026", rightEdge, lineY + titleSize * 0.2); // Draw the year text

  pop(); // Restore the drawing state
}

function initLayout() {
  grid = []; // Clear the existing grid array
  let minSide = max(width, height); // Get the smallest dimension for responsive scaling
  cellSize = minSide / 9; // Calculate cell size based on screen size
  uiHeight = cellSize * 2.5; // Reserve space for the bottom UI

  cols = floor((width - cellSize) / cellSize); // Calculate number of columns
  rows = floor((height - uiHeight - cellSize) / cellSize); // Calculate number of rows

  marginX = (width - (cols - 1) * cellSize) / 2; // Calculate horizontal margin for centering
  marginY = (height - uiHeight - (rows - 1) * cellSize) / 2; // Calculate vertical margin for centering

  for (let i = 0; i < cols; i++) { // Loop through columns
    for (let j = 0; j < rows; j++) { // Loop through rows
      grid.push({ // Create and store a new cell object
        x: marginX + i * cellSize, // Calculate x position
        y: marginY + j * cellSize, // Calculate y position
        color: random(COLORS), // Assign a random color
        shapeType: floor(random(5)), // Assign a random shape type
        targetAngle: floor(random(4)) * HALF_PI, // Set an initial target rotation
        currentAngle: floor(random(4)) * HALF_PI, // Set an initial starting rotation
        timer: random(100, 300) // Assign a random time until the next rotation
      });
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); // Resize the canvas to fit the new window size
  initLayout(); // Re-initialize the layout for the new dimensions
}

function mousePressed() {
  initLayout(); // Reset and randomize the layout when the mouse is pressed
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
